CREATE TABLE users (id UUID PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, display_name VARCHAR(120) NOT NULL, role VARCHAR(32) NOT NULL CHECK (role IN ('PATIENT','CAREGIVER','CLINICIAN_REVIEWER','ADMIN')), status VARCHAR(24) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE patient_profiles (id UUID PRIMARY KEY, user_id UUID NOT NULL UNIQUE REFERENCES users(id), preferred_name VARCHAR(120) NOT NULL, preferred_language VARCHAR(16) NOT NULL DEFAULT 'en', accessibility_preferences TEXT NOT NULL DEFAULT '{}', emergency_contact VARCHAR(255), consent_status VARCHAR(24) NOT NULL DEFAULT 'PENDING', created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE caregiver_patient_links (id UUID PRIMARY KEY, caregiver_id UUID NOT NULL REFERENCES users(id), patient_id UUID NOT NULL REFERENCES patient_profiles(id), relationship_label VARCHAR(80), permissions TEXT NOT NULL DEFAULT '{}', active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(caregiver_id, patient_id));
CREATE TABLE consent_records (id UUID PRIMARY KEY, patient_id UUID NOT NULL REFERENCES patient_profiles(id), purpose VARCHAR(120) NOT NULL, status VARCHAR(24) NOT NULL, granted_at TIMESTAMP WITH TIME ZONE, revoked_at TIMESTAMP WITH TIME ZONE, recorded_by UUID REFERENCES users(id));
CREATE TABLE audit_logs (id UUID PRIMARY KEY, actor_id UUID REFERENCES users(id), action VARCHAR(100) NOT NULL, resource_type VARCHAR(100) NOT NULL, resource_id VARCHAR(100), metadata TEXT NOT NULL DEFAULT '{}', created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_caregiver_link_active ON caregiver_patient_links(caregiver_id, active);
CREATE INDEX idx_audit_actor_created ON audit_logs(actor_id, created_at DESC);
